args.content:
import { forbidden } from 'next/navigation'
import { getSession } from '@/app/lib/auth'

export default async function AdminPage() {
  const session = await getSession()

  // Auth boundary: authenticated users without the 'admin' role get a 403.
  // `forbidden()` throws and renders forbidden.tsx with a 403 status code.
  if (session?.role !== 'admin') {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session.name}!</p>
      <p>You have admin access to manage the application.</p>
    </main>
  )
}

